package com.proofclean.analysis.service;
import com.proofclean.analysis.entity.*;import com.proofclean.common.exception.*;import com.proofclean.common.util.FileNameUtils;import com.proofclean.config.FileStorageConfig;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;import javax.imageio.ImageIO;import java.awt.image.BufferedImage;import java.io.IOException;import java.nio.file.*;import java.util.Set;
@Service @RequiredArgsConstructor
public class FileStorageService { private final FileStorageConfig config; private static final Set<String> TYPES=Set.of("image/jpeg","image/png","image/webp","application/pdf"); public UploadedFile store(AnalysisProject project, MultipartFile file){ if(file.isEmpty()) throw new BadRequestException("빈 파일은 업로드할 수 없습니다."); if(!TYPES.contains(file.getContentType())) throw new BadRequestException("지원하지 않는 파일 형식입니다."); try{Files.createDirectories(Path.of(config.originalDir)); String stored=FileNameUtils.uuidName(file.getOriginalFilename()); Path path=Path.of(config.originalDir).resolve(stored).normalize(); file.transferTo(path); Integer w=null,h=null; if(file.getContentType()!=null&&file.getContentType().startsWith("image/")){ BufferedImage img=ImageIO.read(path.toFile()); if(img!=null){w=img.getWidth();h=img.getHeight();}} return UploadedFile.builder().analysisProject(project).originalFileName(file.getOriginalFilename()).storedFileName(stored).filePath(path.toString()).fileType(file.getContentType()!=null&&file.getContentType().startsWith("image/")?"IMAGE":"PDF").mimeType(file.getContentType()).fileSize(file.getSize()).width(w).height(h).build(); } catch(IOException e){ throw new BadRequestException("파일 저장에 실패했습니다: "+e.getMessage()); } } }
